/**
 * Contrast matrix for every theme scope (light, dark, each preset in both).
 * Reads the CSS, resolves var() and color-mix(in oklab, …), flattens alpha
 * over the surface, and checks WCAG ratios. Turning a knob that breaks
 * legibility fails here, not in production.
 */
import fs from "node:fs"
import path from "node:path"
import { describe, expect, it } from "vitest"
import { converter, formatRgb, parse, wcagContrast, type Color } from "culori"
import { loadConfig, root, themePaths } from "./guard-lib"

type Decls = Record<string, string>
const cfg = loadConfig()

function blocks(css: string) {
  const out: { selector: string; decls: Decls }[] = []
  const clean = css.replace(/\/\*[\s\S]*?\*\//g, "")
  for (const m of clean.matchAll(/([^{}@]+)\{([^{}]*)\}/g)) {
    const decls: Decls = {}
    for (const d of m[2].matchAll(/(--[\w-]+)\s*:\s*([^;]+);/g)) decls[d[1]] = d[2].trim()
    const selector = m[1].split(";").pop()!.trim()
    if (Object.keys(decls).length) out.push({ selector, decls })
  }
  return out
}

const all = themePaths(cfg)
  .filter((f) => fs.existsSync(path.join(root, f)))
  .flatMap((f) => blocks(fs.readFileSync(path.join(root, f), "utf8")))

const pick = (pred: (sel: string) => boolean) =>
  all.filter((b) => b.selector.split(",").some((s) => pred(s.trim()))).reduce<Decls>((acc, b) => ({ ...acc, ...b.decls }), {})

const presets = [...new Set(all.flatMap((b) => [...b.selector.matchAll(/data-theme="([\w-]+)"/g)].map((m) => m[1])))]

const scopes: Record<string, Decls> = {
  light: pick((s) => s === ":root"),
  dark: { ...pick((s) => s === ":root"), ...pick((s) => s === ".dark") },
}
for (const p of presets) {
  const light = pick((s) => s === `[data-theme="${p}"]`)
  const dark = pick((s) => s === `.dark[data-theme="${p}"]` || s === `[data-theme="${p}"] .dark`)
  scopes[`${p} light`] = { ...scopes.light, ...light }
  scopes[`${p} dark`] = { ...scopes.dark, ...light, ...dark }
}

const toLab = converter("oklab")

function resolve(value: string, decls: Decls, depth = 0): Color {
  if (depth > 20) throw new Error(`var() cycle in ${value}`)
  const v = value.trim()
  const ref = v.match(/^var\((--[\w-]+)\)$/)
  if (ref) {
    if (!decls[ref[1]]) throw new Error(`undefined ${ref[1]}`)
    return resolve(decls[ref[1]], decls, depth + 1)
  }
  const mix = v.match(/^color-mix\(\s*in\s+oklab\s*,\s*(.+?)\s+(\d+(?:\.\d+)?)%\s*,\s*(.+)\)$/)
  if (mix) {
    const a = toLab(resolve(mix[1], decls, depth + 1))
    const b = toLab(resolve(mix[3], decls, depth + 1))
    const p = Number(mix[2]) / 100
    const lerp = (x = 0, y = 0) => x * p + y * (1 - p)
    return { mode: "oklab", l: lerp(a.l, b.l), a: lerp(a.a, b.a), b: lerp(a.b, b.b), alpha: lerp(a.alpha ?? 1, b.alpha ?? 1) }
  }
  const c = parse(v)
  if (!c) throw new Error(`can't parse colour "${v}"`)
  return c
}

/** Composite a translucent colour over an opaque one. */
function over(fg: Color, bg: Color): Color {
  const a = fg.alpha ?? 1
  if (a >= 1) return fg
  const rgb = converter("rgb")
  const f = rgb(fg)
  const b = rgb(bg)
  return { mode: "rgb", r: f.r * a + b.r * (1 - a), g: f.g * a + b.g * (1 - a), b: f.b * a + b.b * (1 - a) }
}

const surfaces = ["--background", "--sunken", "--popover"]
const rules: [fg: string, bgs: string[], min: number][] = [
  ["--foreground", [...surfaces, "--muted", "--selected", "--destructive-subtle"], 7],
  ["--muted-foreground", [...surfaces, "--muted", "--selected"], 4.5],
  ["--faint-foreground", surfaces, 4.5],
  ["--primary-foreground", ["--primary"], 4.5],
  ["--background", ["--destructive"], 4.5],
  ["--inverse-foreground", ["--inverse"], 4.5],
  ["--destructive", ["--background", "--popover", "--destructive-subtle"], 4.5],
  ["--success", ["--background", "--popover", "--success-subtle"], 4.5],
  ["--warning", ["--background", "--popover", "--warning-subtle"], 4.5],
  ["--info", ["--background", "--popover", "--info-subtle"], 4.5],
  ["--primary", ["--background", "--popover"], 3],
  ["--ring", ["--background", "--popover"], 3],
]

// Categorical colours (--cat-<name>, user-chosen tag / project / series colours): every one the
// theme declares is text on the canvas, on floating surfaces and on its own -subtle fill.
const categorical = [...new Set(Object.keys(scopes.light).flatMap((k) => k.match(/^--cat-([a-z]+)$/)?.[1] ?? []))]
for (const c of categorical) rules.push([`--cat-${c}`, [...surfaces, `--cat-${c}-subtle`], 4.5])

// Tokens every scope must define and resolve; a missing one means broken
// focus rings or invisible text, not a skipped check.
const required = [...new Set(rules.flatMap(([fg, bgs]) => [fg, ...bgs]))]

describe("theme contrast", () => {
  it("finds the theme", () => {
    expect(Object.keys(scopes.light).length, `no :root tokens in ${cfg.themeFiles.join(", ")}`).toBeGreaterThan(10)
  })

  for (const [scope, decls] of Object.entries(scopes)) {
    it(`${scope}: text and accents meet WCAG`, () => {
      const fails: string[] = []
      for (const t of required) {
        try {
          resolve(`var(${t})`, decls)
        } catch (e) {
          fails.push(`${t}: ${(e as Error).message}`)
        }
      }
      expect(fails, `Missing or broken tokens:\n${fails.join("\n")}`).toEqual([])
      const canvas = resolve("var(--background)", decls)
      for (const [fg, bgs, min] of rules) {
        for (const bg of bgs) {
          const b = over(resolve(`var(${bg})`, decls), canvas)
          const f = over(resolve(`var(${fg})`, decls), b)
          const r = wcagContrast(f, b)
          if (r < min) fails.push(`${fg} on ${bg}: ${r.toFixed(2)} < ${min}  (${formatRgb(f)} on ${formatRgb(b)})`)
        }
      }
      expect(fails, fails.join("\n")).toEqual([])
    })
  }
})

/**
 * Design guards: values come from the theme, overlays from the kit.
 * Fix the code, or add `design-allow: <reason>` on the line.
 */
import { describe, expect, it } from "vitest"
import path from "node:path"
import { isCommentLine, loadConfig, report, scan, sourceFiles } from "./guard-lib"

const cfg = loadConfig()
const files = sourceFiles(cfg)

const palette =
  "slate|gray|zinc|neutral|stone|red|orange|amber|yellow|lime|green|emerald|teal|cyan|sky|blue|indigo|violet|purple|fuchsia|pink|rose"
const utilities = "bg|text|border|border-[trblxy]|ring|ring-offset|outline|fill|stroke|from|via|to|divide|decoration|placeholder|caret|accent|shadow"

describe("design guards", () => {
  it("scans some files", () => {
    expect(files.length).toBeGreaterThan(0)
  })

  it("uses no raw colours outside the theme", () => {
    // Comments are skipped: "(#123)" there is an issue or PR number, not a colour.
    const hex = scan(files, /(^|[\s"'`(:,=[])#(?:[0-9a-fA-F]{3,4}|[0-9a-fA-F]{6}|[0-9a-fA-F]{8})(?![\w-])/, (_, line) => !isCommentLine(line))
    const fn = scan(files, /\b(?:rgba?|hsla?|oklch|oklab|lab|lch|hwb)\(\s*[\d.]/)
    const named = scan(files, new RegExp(`(?<![\\w-])(?:${utilities})-(?:white|black|(?:${palette})-\\d{2,3})(?![\\w-])`))
    const arbitrary = scan(files, new RegExp(`(?<![\\w-])(?:${utilities})-\\[(?:#|rgb|hsl|oklch)`))
    const hits = [...hex, ...fn, ...named, ...arbitrary]
    expect(hits, `Raw colours — use semantic tokens (bg-background, text-muted-foreground, …):\n${report(hits)}`).toEqual([])
  })

  it("keeps text at 12px or larger, from the type scale", () => {
    const small = (px: string) => Number(px) < 12
    const tw = scan(files, /\btext-\[(\d+(?:\.\d+)?)px\]/, (m) => small(m[1]))
    const tw2 = scan(files, /\btext-\[\d/, () => true) // any arbitrary size, small or not
    const css = scan(files, /font-size:\s*(\d+(?:\.\d+)?)px/, (m) => small(m[1]))
    const rn = scan(files, /fontSize:\s*(\d+(?:\.\d+)?)/, (m) => small(m[1]))
    const tiny = scan(files, /\btext-(?:2xs|\[0?\.\d+rem\])/)
    const hits = [...new Map([...tw, ...tw2, ...css, ...rn, ...tiny].map((h) => [`${h.file}:${h.line}`, h])).values()]
    expect(hits, `Type outside the scale — use text-caption … text-hero:\n${report(hits)}`).toEqual([])
  })

  it("uses the kit for dialogs and overlays", () => {
    const native = scan(files, /\b(?:window\.)?(?:alert|confirm|prompt)\(\s*["'`]/)
    const winNative = scan(files, /\bwindow\.(?:alert|confirm|prompt)\(/)
    const uiDirs = cfg.uiDirs.map((d) => path.normalize(d) + path.sep)
    const outsideKit = files.filter((f) => !uiDirs.some((d) => path.normalize(f).startsWith(d)))
    const handRolled = scan(outsideKit, /\bfixed\s+inset-0\b/)
    const hits = [...native, ...winNative, ...handRolled]
    expect(hits, `Use Dialog / Drawer / ConfirmDialog / notify from the kit:\n${report(hits)}`).toEqual([])
  })

  it("uses no emoji as icons", () => {
    const hits = scan(files, /\p{Emoji_Presentation}/u, (_m, line) => !line.trim().startsWith("//") && !line.trim().startsWith("*"))
    expect(hits, `Icons come from lucide-react, not emoji:\n${report(hits)}`).toEqual([])
  })
})

/**
 * Shared helpers for the design guards. Config comes from
 * design-guard.config.json at the project root (all keys optional):
 *   sourceDirs   folders to scan                      ["src"]
 *   themeFiles   files allowed to hold raw values     ["src/styles/jim-theme.css"]
 *   presetFiles  preset css files or folders          ["src/styles/presets"]
 *   uiDirs       kit folders allowed to build overlays ["src/components/ui"]
 *   ignore       path substrings to skip              []
 * Any line can opt out with a reason: `design-allow: <why>` on that line or
 * the line above. No reason, no exception.
 */
import fs from "node:fs"
import path from "node:path"

export type GuardConfig = {
  sourceDirs: string[]
  themeFiles: string[]
  presetFiles: string[]
  uiDirs: string[]
  ignore: string[]
}

export const root = process.cwd()

export function loadConfig(): GuardConfig {
  const file = path.join(root, "design-guard.config.json")
  const user = fs.existsSync(file) ? JSON.parse(fs.readFileSync(file, "utf8")) : {}
  return {
    sourceDirs: ["src"],
    themeFiles: ["src/styles/jim-theme.css"],
    presetFiles: ["src/styles/presets"],
    uiDirs: ["src/components/ui"],
    ignore: [],
    ...user,
  }
}

const exts = /\.(tsx?|jsx?|vue|svelte|css|scss)$/

export function walk(dir: string, out: string[] = []): string[] {
  const abs = path.join(root, dir)
  if (!fs.existsSync(abs)) return out
  if (fs.statSync(abs).isFile()) return exts.test(abs) ? [...out, dir] : out
  for (const e of fs.readdirSync(abs, { withFileTypes: true })) {
    if (e.name === "node_modules" || e.name.startsWith(".")) continue
    const rel = path.join(dir, e.name)
    if (e.isDirectory()) walk(rel, out)
    else if (exts.test(e.name)) out.push(rel)
  }
  return out
}

export function themePaths(cfg: GuardConfig) {
  return [...cfg.themeFiles, ...cfg.presetFiles.flatMap((p) => walk(p))].map((p) => path.normalize(p))
}

export function sourceFiles(cfg: GuardConfig) {
  const theme = new Set(themePaths(cfg))
  return cfg.sourceDirs
    .flatMap((d) => walk(d))
    .filter((f) => !theme.has(path.normalize(f)))
    .filter((f) => !/\.test\.[tj]sx?$/.test(f) && !f.includes(`${path.sep}guards${path.sep}`))
    .filter((f) => !cfg.ignore.some((i) => f.includes(i)))
}

export type Hit = { file: string; line: number; text: string }

/** Lines matching `re`, minus those carrying a `design-allow: reason`. */
export function scan(files: string[], re: RegExp, keep: (m: RegExpMatchArray, line: string) => boolean = () => true): Hit[] {
  const hits: Hit[] = []
  for (const file of files) {
    const lines = fs.readFileSync(path.join(root, file), "utf8").split("\n")
    lines.forEach((line, i) => {
      const allowed = /design-allow:\s*\S/.test(line) || /design-allow:\s*\S/.test(lines[i - 1] ?? "")
      if (allowed) return
      for (const m of line.matchAll(new RegExp(re.source, re.flags.includes("g") ? re.flags : re.flags + "g"))) {
        if (keep(m, line)) {
          hits.push({ file, line: i + 1, text: line.trim().slice(0, 140) })
          break
        }
      }
    })
  }
  return hits
}

/** A line that is only a comment (`//`, `/*`, ` * `, `<!--`): it can't style anything. */
export function isCommentLine(line: string) {
  return /^\s*(?:\/\/|\/\*|\*|<!--)/.test(line)
}

export function report(hits: Hit[]) {
  return hits.map((h) => `  ${h.file}:${h.line}  ${h.text}`).join("\n")
}
